new Promise(resolve => {
  const start = Date.now();
  const check = () => {
    const href = window.location.href;
    const body = document.body.innerText.slice(0, 300);
    if (href.includes('files') || Date.now() - start > 45000) {
      resolve(JSON.stringify({href, body}));
    } else setTimeout(check, 1500);
  };
  check();
})

(() => {
  if (!window.__uatErrors) {
    window.__uatErrors = [];
    window.__uatWarns = [];
    const origErr = console.error.bind(console);
    const origWarn = console.warn.bind(console);
    console.error = (...a) => { window.__uatErrors.push(a.map(x => String(x?.message || x)).join(' ').slice(0,300)); origErr(...a); };
    console.warn = (...a) => { window.__uatWarns.push(a.map(x => String(x?.message || x)).join(' ').slice(0,300)); origWarn(...a); };
    window.addEventListener('error', e => window.__uatErrors.push('window.onerror: ' + e.message));
    window.addEventListener('unhandledrejection', e => window.__uatErrors.push('unhandledrejection: ' + String(e.reason).slice(0,300)));
  }
  return 'collector installed';
})()

(() => {
  const inputs = Array.from(document.querySelectorAll('input[type="file"]')).map(i => ({cls: i.className, parent: i.parentElement?.className, multiple: i.multiple}));
  return JSON.stringify(inputs);
})()

(() => {
  const input = document.querySelector('.upload-zone input[type="file"]');
  const file = new File(['CipherBox UAT 19.1 test file — uploaded via Puppeteer on 2026-06-10.\n' + 'x'.repeat(2048)], 'uat-19-1-test.txt', { type: 'text/plain' });
  const dt = new DataTransfer();
  dt.items.add(file);
  input.files = dt.files;
  input.dispatchEvent(new Event('change', { bubbles: true }));
  return 'change dispatched with uat-19-1-test.txt (' + file.size + ' bytes)';
})()

new Promise(resolve => {
  const start = Date.now();
  const check = () => {
    const items = Array.from(document.querySelectorAll('.file-list-item')).map(el => el.innerText.replace(/\n/g, ' | ').slice(0, 100));
    const hasFile = items.some(t => t.includes('uat-19-1-test.txt'));
    const uploading = items.some(t => /upload|%/i.test(t));
    if ((hasFile && !uploading) || Date.now() - start > 60000) {
      resolve(JSON.stringify({items, errors: window.__uatErrors, elapsed: Date.now() - start}));
    } else setTimeout(check, 1000);
  };
  check();
})

new Promise(resolve => setTimeout(() => {
  const row = Array.from(document.querySelectorAll('.file-list-item')).find(el => el.innerText.includes('uat-19-1-test.txt'));
  resolve(JSON.stringify({
    rowHtml: row ? row.outerHTML.slice(0, 1200) : 'GONE',
    errors: window.__uatErrors,
    warns: window.__uatWarns.slice(-5)
  }));
}, 3000))

(() => {
  // snapshot resource count, then retry
  window.__resMark = performance.getEntriesByType('resource').length;
  window.__uatErrors.length = 0;
  document.querySelector('.upload-inline-btn--retry').click();
  return 'retry clicked';
})()

new Promise(resolve => setTimeout(() => {
  const res = performance.getEntriesByType('resource').slice(window.__resMark).map(r => ({name: r.name.replace('http://localhost:5173',''), status: r.responseStatus, dur: Math.round(r.duration)}));
  const row = Array.from(document.querySelectorAll('.file-list-item')).find(el => el.innerText.includes('uat-19-1-test.txt'));
  resolve(JSON.stringify({
    network: res,
    rowClass: row ? row.className : 'GONE',
    rowText: row ? row.innerText.replace(/\n/g,' | ') : '',
    errors: window.__uatErrors
  }, null, 1));
}, 8000))

