  const row = Array.from(document.querySelectorAll('.upload-inline-row')).find(el => el.innerText.includes('uat-19-1-test.txt'));
  if (!row) return 'row gone';
  const fiberKey = Object.keys(row).find(k => k.startsWith('__reactFiber$'));
  let fiber = row[fiberKey];
  for (let i = 0; i < 10 && fiber; i++) {
    const props = fiber.memoizedProps;
    if (props && props.file && props.file.status) {
      return JSON.stringify({status: props.file.status, error: props.file.error, progress: props.file.progress, name: props.file.fileName || props.file.name});
    }
    fiber = fiber.return;
  }
  return 'no file prop found';
})()

(() => {
  const row = Array.from(document.querySelectorAll('.upload-inline-row')).find(el => el.innerText.includes('uat-19-1-test.txt'));
  if (!row) return 'row gone';
  const fiberKey = Object.keys(row).find(k => k.startsWith('__reactFiber$'));
  let fiber = row[fiberKey];
  const seen = [];
  for (let i = 0; i < 25 && fiber; i++) {
    const props = fiber.memoizedProps;
    if (props && typeof props === 'object') {
      const keys = Object.keys(props).slice(0, 10);
      seen.push(i + ':' + keys.join(','));
      for (const k of keys) {
        const v = props[k];
        if (v && typeof v === 'object' && ('status' in v) && ('error' in v)) {
          return JSON.stringify({foundAt: k, status: v.status, error: String(v.error).slice(0, 400), progress: v.progress});
        }
      }
    }
    fiber = fiber.return;
  }
  return 'NOT FOUND. fibers: ' + seen.join(' | ').slice(0, 800);
})()

(() => {
  window.__netLog = [];
  if (!window.__fetchPatched) {
    window.__fetchPatched = true;
    const origFetch = window.fetch.bind(window);
    window.fetch = async (...args) => {
      const url = String(args[0]?.url || args[0]).slice(0, 150);
      try {
        const r = await origFetch(...args);
        window.__netLog.push({url, status: r.status});
        return r;
      } catch (e) {
        window.__netLog.push({url, threw: String(e).slice(0, 200)});
        throw e;
      }
    };
    const origSend = XMLHttpRequest.prototype.send;
    const origOpen = XMLHttpRequest.prototype.open;
    XMLHttpRequest.prototype.open = function(m, u, ...rest) { this.__url = u; return origOpen.call(this, m, u, ...rest); };
    XMLHttpRequest.prototype.send = function(...a) {
      this.addEventListener('loadend', () => window.__netLog.push({xhr: String(this.__url).slice(0,150), status: this.status}));
      return origSend.apply(this, a);
    };
  }
  window.__uatErrors.length = 0; window.__uatWarns.length = 0;
  const btn = document.querySelector('.upload-inline-btn--retry');
  if (!btn) return 'no retry button';
  btn.click();
  return 'retry clicked, instrumentation live';
})()

new Promise(resolve => setTimeout(() => {
  const row = Array.from(document.querySelectorAll('.upload-inline-row')).find(el => el.innerText.includes('uat-19-1-test.txt'));
  resolve(JSON.stringify({
    net: window.__netLog,
    errors: window.__uatErrors,
    warns: window.__uatWarns,
    rowClass: row ? row.className.match(/--\w+/g) : 'GONE'
  }, null, 1));
}, 10000))

