(() => {
  const row = Array.from(document.querySelectorAll('.upload-inline-row')).find(el => el.innerText.includes('uat-19-1-test.txt'));
  if (!row) return 'row gone';
  const fiberKey = Object.keys(row).find(k => k.startsWith('__reactFiber$'));
  let fiber = row[fiberKey];
  // walk up to the UploadListItem function component
  while (fiber && !(typeof fiber.type === 'function' && /UploadListItem/.test(fiber.type.name || ''))) fiber = fiber.return;
  if (!fiber) return 'UploadListItem fiber not found';
  // walk hook chain
  let hook = fiber.memoizedState;
  const found = [];
  for (let i = 0; i < 20 && hook; i++) {
    const v = hook.memoizedState;
    const inspect = (x) => x && typeof x === 'object' && 'status' in x && 'error' in x;
    if (inspect(v)) { found.push(v); }
    else if (v && typeof v === 'object' && inspect(v.value)) { found.push(v.value); }
    hook = hook.next;
  }
  if (found.length) {
    const f = found[0];
    return JSON.stringify({status: f.status, error: String(f.error).slice(0, 500), filename: f.filename, progress: f.progress});
  }
  return 'no matching hook state';
})()

