new Promise(resolve => {
  const start = Date.now();
  const check = () => {
    const xhr = new XMLHttpRequest();
    xhr.open('GET', 'http://localhost:3000/migration/status');
    const token = (() => { try { return JSON.parse(sessionStorage.getItem('auth') || '{}'); } catch { return {}; } })();
    xhr.withCredentials = true;
    xhr.onload = () => {
      let body; try { body = JSON.parse(xhr.responseText); } catch { body = xhr.responseText.slice(0,200); }
      const st = body?.status || body?.state || JSON.stringify(body).slice(0,150);
      if (/complete|done|finished|none|idle/i.test(String(st)) || Date.now() - start > 30000) resolve(JSON.stringify({httpStatus: xhr.status, body: typeof body === 'object' ? JSON.stringify(body).slice(0,300) : body}));
