new Promise(resolve => {
  const start = Date.now();
  const check = () => {
    if (window.location.hash.includes('files') && (document.querySelector('.file-list[role="grid"]') || document.querySelector('[data-testid="empty-state"]'))) {
      // re-install collectors after fresh page
      window.__uatErrors = []; window.__uatWarns = []; window.__netLog = [];
      const oe = console.error.bind(console), ow = console.warn.bind(console);
      console.error = (...a) => { window.__uatErrors.push(a.map(x => String(x?.message || x)).join(' ').slice(0,300)); oe(...a); };
      console.warn = (...a) => { window.__uatWarns.push(a.map(x => String(x?.message || x)).join(' ').slice(0,300)); ow(...a); };
      window.addEventListener('error', e => window.__uatErrors.push('window.onerror: ' + e.message));
      window.addEventListener('unhandledrejection', e => window.__uatErrors.push('unhandledrejection: ' + String(e.reason).slice(0,300)));
      const origSend = XMLHttpRequest.prototype.send, origOpen = XMLHttpRequest.prototype.open;
      XMLHttpRequest.prototype.open = function(m, u, ...rest) { this.__url = u; return origOpen.call(this, m, u, ...rest); };
      XMLHttpRequest.prototype.send = function(...a) { this.addEventListener('loadend', () => window.__netLog.push({xhr: String(this.__url).replace('http://localhost:3000','').slice(0,120), status: this.status})); return origSend.apply(this, a); };
      resolve('logged in, vault loaded, collectors re-installed');
